(1985776, 272624, 15711, '<td valign="top">This is an adorable portrait. I like the angle from which you took it.  Her impish grin is adorable. I like the background being light but not bright white too.</td>', 'This is an adorable portrait. I like the angle from which you took it.  Her impish grin is adorable. I like the background being light but not bright white too.', '2005-12-29 08:59:13.000000', NULL, 1),
(1985778, 271787, 15711, '<td valign="top">Great DOF! I like that he''s way to the left with the blurred area of leaves behind hin. His profile almost is the miniature of the long leaf directly behind him. Nicely done.</td>', 'Great DOF! I like that he''s way to the left with the blurred area of leaves behind hin. His profile almost is the miniature of the long leaf directly behind him. Nicely done.', '2005-12-29 09:00:03.000000', NULL, 1),
