(1988712, 272066, 47852, '<td valign="top">Good timing on snapping this one... just a tad out of focus, but the eagle''s wing position is great with the outstretched feathers.</td>', 'Good timing on snapping this one... just a tad out of focus, but the eagle''s wing position is great with the outstretched feathers.', '2005-12-30 15:45:24.000000', NULL, 1),
(1988727, 272448, 50322, '<td valign="top">The colors are really nice on the black background. I think the user name could be a little bit more creative though.</td>', 'The colors are really nice on the black background. I think the user name could be a little bit more creative though.', '2005-12-30 15:54:54.000000', NULL, 1),
(1988758, 272350, 23430, '<td valign="top">Nice tones. Looks peaceful.</td>', 'Nice tones. Looks peaceful.', '2005-12-30 16:12:13.000000', NULL, 1),
(1988760, 271508, 23430, '<td valign="top">I like the light reflecting off the water. I think I would rather see the front of the Lilly though. Still the composition is fairly good and the focus is good.</td>', 'I like the light reflecting off the water. I think I would rather see the front of the Lilly though. Still the composition is fairly good and the focus is good.', '2005-12-30 16:15:29.000000', NULL, 1),
(1988772, 272624, 23430, '<td valign="top">Nice picture. Cute kid and good lighting and background. She doesn''t have an expression of coolness though. Her looking away from the camera looks a bit funny too.</td>', 'Nice picture. Cute kid and good lighting and background. She doesn''t have an expression of coolness though. Her looking away from the camera looks a bit funny too.', '2005-12-30 16:19:46.000000', NULL, 1),
(1988776, 270955, 23430, '<td valign="top">I like this abstract work. It looks like the pieces are at different levels as well (not on a 2D plain) to me which really adds to the effect.</td>', 'I like this abstract work. It looks like the pieces are at different levels as well (not on a 2D plain) to me which really adds to the effect.', '2005-12-30 16:22:13.000000', NULL, 1),
(1988783, 271663, 23430, '<td valign="top">Great expression and lighting. My only pick is the slight out of focus arm on the right. I think it was still better to leave it in the composition though rather than crop it out so well done..</td>', 'Great expression and lighting. My only pick is the slight out of focus arm on the right. I think it was still better to leave it in the composition though rather than crop it out so well done..', '2005-12-30 16:25:40.000000', NULL, 1),
(1988786, 271553, 23430, '<td valign="top">The big sky you have chosen to go with is good.</td>', 'The big sky you have chosen to go with is good.', '2005-12-30 16:26:52.000000', NULL, 1),
(1988793, 272440, 23430, '<td valign="top">The nice light coming off the bushes in the foreground makes this a really nicely balanced composition. You have adjusted or left the darkness in the hills just right and the sky and sun look great.</td>', 'The nice light coming off the bushes in the foreground makes this a really nicely balanced composition. You have adjusted or left the darkness in the hills just right and the sky and sun look great.', '2005-12-30 16:30:46.000000', NULL, 1),
(1988804, 271116, 23430, '<td valign="top">This is a good subject, composition and I like your background. The only thing for me is the light striking from behind doesn''t help.</td>', 'This is a good subject, composition and I like your background. The only thing for me is the light striking from behind doesn''t help.', '2005-12-30 16:34:22.000000', NULL, 1),
(1988813, 272612, 23430, '<td valign="top">Great depiction of this username. Having the 2 elements on opposing corners and taking up the right proportion of space. The out of focus background and the water drop all add to this shot. The colours are also great.</td>', 'Great depiction of this username. Having the 2 elements on opposing corners and taking up the right proportion of space. The out of focus background and the water drop all add to this shot. The colours are also great.', '2005-12-30 16:38:09.000000', NULL, 1),
(1988819, 271703, 23430, '<td valign="top">The different level of brightness and tones of the silhouettes in this shot are great.</td>', 'The different level of brightness and tones of the silhouettes in this shot are great.', '2005-12-30 16:41:28.000000', NULL, 1),
(1988833, 272148, 23430, '<td valign="top">Love the expression and general composition. The focus on the mouth is perfect but it would also be good to see that same very sharp focus on the eyes as well. That''s only noticeable when you are looking for it so I think it''s still a very good shot.</td>', 'Love the expression and general composition. The focus on the mouth is perfect but it would also be good to see that same very sharp focus on the eyes as well. That''s only noticeable when you are looking for it so I think it''s still a very good shot.', '2005-12-30 16:45:44.000000', NULL, 1),
(1988837, 272253, 4793, '<td valign="top">Beautiful shot</td>', 'Beautiful shot', '2005-12-30 16:46:28.000000', NULL, 1),
