(1988846, 272034, 4793, '<td valign="top">Different</td>', 'Different', '2005-12-30 16:51:24.000000', NULL, 1),
(1988851, 272529, 23430, '<td valign="top">Great look on the tigers face. I like the crop and the clarity of this shot. You have picked the exact right point for your centre of your DOF, from the nose back to the eyes are all sharp before the focus drops away. I''m guessing you used a long zoom as the shot is slightly flat but I guess that''s usually necessary when taking pictures of something that could eat you. I don''t think your border has helped this shot but overall it''s a great photo.</td>', 'Great look on the tigers face. I like the crop and the clarity of this shot. You have picked the exact right point for your centre of your DOF, from the nose back to the eyes are all sharp before the focus drops away. I''m guessing you used a long zoom as the shot is slightly flat but I guess that''s usually necessary when taking pictures of something that could eat you. I don''t think your border has helped this shot but overall it''s a great photo.', '2005-12-30 16:54:07.000000', NULL, 1),
(1988876, 271488, 42005, '<td valign="top">Truly gorgeous. This will be a ribbon winner for sure. 9</td>', 'Truly gorgeous. This will be a ribbon winner for sure. 9', '2005-12-30 17:11:37.000000', NULL, 1),
