(1990602, 272243, 22734, '<td valign="top">A wonderful capture with cobble stones to awaken a pleasant nostalgic feel. Bumpimg up.</td>', 'A wonderful capture with cobble stones to awaken a pleasant nostalgic feel. Bumpimg up.', '2005-12-31 13:05:46.000000', NULL, 1),
(1990739, 271803, 4793, '<td valign="top">Very nice details, good shot</td>', 'Very nice details, good shot', '2005-12-31 14:55:37.000000', NULL, 1),
(1990745, 271282, 4793, '<td valign="top">Beautiful winter shot, I like this scene</td>', 'Beautiful winter shot, I like this scene', '2005-12-31 14:59:32.000000', NULL, 1),
(1990747, 272328, 4793, '<td valign="top">Beautiful colors</td>', 'Beautiful colors', '2005-12-31 14:59:44.000000', NULL, 1),
(1990829, 272319, 35602, '<td valign="top">The image seemed very dark.  Perhaps it is my monitor but I only see a few light  lines.  I can only vote on what I am seeing.  Maybe a bit more brightness in the editing would have brought it out better.</td>', 'The image seemed very dark.  Perhaps it is my monitor but I only see a few light  lines.  I can only vote on what I am seeing.  Maybe a bit more brightness in the editing would have brought it out better.', '2005-12-31 16:15:28.000000', NULL, 1),
(1990832, 272622, 35602, '<td valign="top">Nice stop action.  Love the shadow in the background.  The distortion also added to the motion of the image.  The only thing I didn''t like was the person sitting in the background.  I think it interfered with the impact of an otherwise terrific picture.</td>', 'Nice stop action.  Love the shadow in the background.  The distortion also added to the motion of the image.  The only thing I didn''t like was the person sitting in the background.  I think it interfered with the impact of an otherwise terrific picture.', '2005-12-31 16:17:34.000000', NULL, 1),
(1990834, 271678, 35602, '<td valign="top">Would have liked to see more light on the amoeba shape.</td>', 'Would have liked to see more light on the amoeba shape.', '2005-12-31 16:18:45.000000', NULL, 1),
(1990837, 272259, 35602, '<td valign="top">Great interpretation of the name.  The blue and black make for a very soothing and restful composition.</td>', 'Great interpretation of the name.  The blue and black make for a very soothing and restful composition.', '2005-12-31 16:20:26.000000', NULL, 1),
(1990840, 272410, 35602, '<td valign="top">The branches distracted from the hawk.  The colors are so close that the hawk isn''t separated enough from them.  Perhaps a different angle where the hawk was singled out better would have improved the composition.</td>', 'The branches distracted from the hawk.  The colors are so close that the hawk isn''t separated enough from them.  Perhaps a different angle where the hawk was singled out better would have improved the composition.', '2005-12-31 16:22:13.000000', NULL, 1),
(1990842, 271798, 35602, '<td valign="top">Nice use of dof.  Good detail on the underside of the leaf.  Could have used more contrast to really bring out the silvery tone of the veins.</td>', 'Nice use of dof.  Good detail on the underside of the leaf.  Could have used more contrast to really bring out the silvery tone of the veins.', '2005-12-31 16:24:06.000000', NULL, 1),
(1990846, 272630, 35602, '<td valign="top">Image seems too muddy.  A bit more contrast on the ladybug would have made it less hazy looking.  It almost seems to have a coating over it.</td>', 'Image seems too muddy.  A bit more contrast on the ladybug would have made it less hazy looking.  It almost seems to have a coating over it.', '2005-12-31 16:26:44.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1990849, 270975, 35602, '<td valign="top">Nice attempt at macro.  The image seemed a bit too muddy.  Maybe the macro made it too noisy.  Loved the color combination on the petals, though. The green graduating to pink was excellent.</td>', 'Nice attempt at macro.  The image seemed a bit too muddy.  Maybe the macro made it too noisy.  Loved the color combination on the petals, though. The green graduating to pink was excellent.', '2005-12-31 16:29:11.000000', NULL, 1),
(1990855, 272448, 17507, '<td valign="top">there is a user ''crayon,'' but not ''crayon go round'' - I''m having trouble understanding why you included ''go round'' in the title other than to state the obvious</td>', 'there is a user ''crayon,'' but not ''crayon go round'' - I''m having trouble understanding why you included ''go round'' in the title other than to state the obvious', '2005-12-31 16:39:26.000000', NULL, 1),
(1990858, 272390, 30669, '<td valign="top">What an EXCELLENT shot. I love it....  10</td>', 'What an EXCELLENT shot. I love it....  10', '2005-12-31 16:51:20.000000', NULL, 1),
(1990930, 272094, 15711, '<td valign="top">I think this just isn''t visual enough.  Yes it meets the challenge, but there just isn''t quite enough eye candy for me, to make it one of those WOW shots. It has potential and I do like dark photos, but for once, this one''s too dark for my taste.  NOt horrible, just with it had a bit more. 6</td>', 'I think this just isn''t visual enough.  Yes it meets the challenge, but there just isn''t quite enough eye candy for me, to make it one of those WOW shots. It has potential and I do like dark photos, but for once, this one''s too dark for my taste.  NOt horrible, just with it had a bit more. 6', '2005-12-31 17:45:22.000000', NULL, 1),
(1990932, 272155, 15711, '<td valign="top">Not a fan of stuffed animals in shots, but I guess it would be kind of hard to have a live one!!  The detail is good and the composition is pleasing. I''m trying, but I can''t get excited about a teddy bear and some sheet music, although it certainly fits his name.  6</td>', 'Not a fan of stuffed animals in shots, but I guess it would be kind of hard to have a live one!!  The detail is good and the composition is pleasing. I''m trying, but I can''t get excited about a teddy bear and some sheet music, although it certainly fits his name.  6', '2005-12-31 17:46:31.000000', NULL, 1),
(1990935, 272625, 15711, '<td valign="top">I think what bugs me most is the blurred bridge of the nose that takes up 1/3 of the shot.  I''d much rather have the entire shot as the macro. That brown eye is beautiful and it''s so clear, but I can''t get past the blur of the nose.  Maybe shoot from a different perspective. This certainly has merit if the ol'' schnoz weren''t there. 6</td>', 'I think what bugs me most is the blurred bridge of the nose that takes up 1/3 of the shot.  I''d much rather have the entire shot as the macro. That brown eye is beautiful and it''s so clear, but I can''t get past the blur of the nose.  Maybe shoot from a different perspective. This certainly has merit if the ol'' schnoz weren''t there. 6', '2005-12-31 17:47:53.000000', NULL, 1),
(1990937, 272588, 15711, '<td valign="top">I like the leading line and the scene is pretty.  A bit ho hum for me though. Maybe too centered for my taste.  Plus the literal translation for me would be "bridge finder" as path denotes dirt/grass on the ground, but that''s just a nitpick comment.   Maybe crop out one side a bit, so the bridge isn''t bullseye centered.  Even black and white with high contrast might be a fun approach to this shot as well.</td>', 'I like the leading line and the scene is pretty.  A bit ho hum for me though. Maybe too centered for my taste.  Plus the literal translation for me would be "bridge finder" as path denotes dirt/grass on the ground, but that''s just a nitpick comment.   Maybe crop out one side a bit, so the bridge isn''t bullseye centered.  Even black and white with high contrast might be a fun approach to this shot as well.', '2005-12-31 17:49:41.000000', NULL, 1),
(1990940, 271918, 15711, '<td valign="top">HEE HEE. This does suit the name, but for some reason kind of leaves me with a "homemade" feeling. Maybe if the trebel clef were printed and not hand drawn.  I do like the perspective and the originality of the idea.</td>', 'HEE HEE. This does suit the name, but for some reason kind of leaves me with a "homemade" feeling. Maybe if the trebel clef were printed and not hand drawn.  I do like the perspective and the originality of the idea.', '2005-12-31 17:50:50.000000', NULL, 1),
(1990941, 272632, 15711, '<td valign="top">That crazy kitty!!!  I have to laugh every time I see this and I''ve viewed it several times. I like the tangle of the lights and the almost "HUH" expression on the cat. I wish there were a touch more light on the kitty''s face.  Still, kinda cute and entertaining.</td>', 'That crazy kitty!!!  I have to laugh every time I see this and I''ve viewed it several times. I like the tangle of the lights and the almost "HUH" expression on the cat. I wish there were a touch more light on the kitty''s face.  Still, kinda cute and entertaining.', '2005-12-31 17:52:26.000000', NULL, 1),
(1990946, 272592, 15711, '<td valign="top">The sentiment is very sweet and I like the idea of it, but with the plaid shirt and the baby''s shirt with the "My First Christmas" on it, it just looks like a quick snapshot and not one that''s very well thought out. I would love it if there were a solid black background and the dad and son either had on maybe black shirts, so that they faded into the backdrop OR no shirts at all, and there was one source of light showcasing facial and shoulder structure.</td>', 'The sentiment is very sweet and I like the idea of it, but with the plaid shirt and the baby''s shirt with the "My First Christmas" on it, it just looks like a quick snapshot and not one that''s very well thought out. I would love it if there were a solid black background and the dad and son either had on maybe black shirts, so that they faded into the backdrop OR no shirts at all, and there was one source of light showcasing facial and shoulder structure.', '2005-12-31 17:55:12.000000', NULL, 1),
(1990949, 272512, 15711, '<td valign="top">Sweet face.  It seems just a tad off to me.  Not really blurred, but almost has a slight haze to it (and I haven''t even been drinking). I''d like to see this adorable pooch with the maximum 640 pixelation too.</td>', 'Sweet face.  It seems just a tad off to me.  Not really blurred, but almost has a slight haze to it (and I haven''t even been drinking). I''d like to see this adorable pooch with the maximum 640 pixelation too.', '2005-12-31 17:56:10.000000', NULL, 1),
(1990951, 272626, 15711, '<td valign="top">I usually love out of the box artsy shots, but this just isn''t doing it for me. I like the use of negative space and the tattoo on the arm is cool, but maybe there just isn''t enough to peak my interest (sigh). And so it goes...........................</td>', 'I usually love out of the box artsy shots, but this just isn''t doing it for me. I like the use of negative space and the tattoo on the arm is cool, but maybe there just isn''t enough to peak my interest (sigh). And so it goes...........................', '2005-12-31 17:57:09.000000', NULL, 1),
(1990952, 272524, 17507, '<td valign="top">great background!</td>', 'great background!', '2005-12-31 17:58:45.000000', NULL, 1),
(1990953, 272447, 15711, '<td valign="top">I like the idea of this. I wish the trees weren''t so orange.  The sky is incriedible and the shimmer from the back to the front of the image is very pleasing. You could almost crop out about 2 inches off of the bottom and the orangy trees on the right, and then zoom in, and it would really have impact for me.</td>', 'I like the idea of this. I wish the trees weren''t so orange.  The sky is incriedible and the shimmer from the back to the front of the image is very pleasing. You could almost crop out about 2 inches off of the bottom and the orangy trees on the right, and then zoom in, and it would really have impact for me.', '2005-12-31 17:58:57.000000', NULL, 1),
(1990955, 272163, 15711, '<td valign="top">I''d crop out the metal structure to the left and just have the guy and the mountains. I like the silhouette and the golden tones. Maybe reduce the dark foreground a bit more too and zoom in on the rider more.</td>', 'I''d crop out the metal structure to the left and just have the guy and the mountains. I like the silhouette and the golden tones. Maybe reduce the dark foreground a bit more too and zoom in on the rider more.', '2005-12-31 17:59:45.000000', NULL, 1),
