INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1994585, 272512, 28710, '<td valign="top">I''m not much a fan of dogs, I''ll admit, but this is a really super pic. I think you did just about everything right in camera.<br/> <br/>I will second the comment about using curves to nail that background to the black point (it''s really easy) and making sure the largest size is 640.<br/> <br/>It''s really beautiful.<br/> <br/>You should repost this pic (with the adjustments) in your portfolio and put a link to it in the comments.</td>', 'I''m not much a fan of dogs, I''ll admit, but this is a really super pic. I think you did just about everything right in camera. I will second the comment about using curves to nail that background to the black point (it''s really easy) and making sure the largest size is 640. It''s really beautiful. You should repost this pic (with the adjustments) in your portfolio and put a link to it in the comments.', '2006-01-02 09:00:03.000000', NULL, 0),
(1994607, 272398, 28710, '<td valign="top">Underrated. Nicely done example of good lighting. Simple is good.<br/> <br/>Seems a tad OOF, and needs some of the left cut off. That fold is rather distracting.<br/> <br/></td>', 'Underrated. Nicely done example of good lighting. Simple is good. Seems a tad OOF, and needs some of the left cut off. That fold is rather distracting. ', '2006-01-02 09:16:20.000000', NULL, 0),
